contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // Single public entry used for property-based testing
    // params: caller address (as target for sendMoney), value to forward from C, arbitrary data for the call
    function run(address target, uint value, bytes calldata data) public payable {
        // preconditions: limit value to avoid overflow reasoning issues
        require(value <= address(c).balance);

        // observe owner to determine whether caller is owner
        address owner = c.owner(); if (__ESBMC_reverted()) return;

        // observe pre-state
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint balanceBefore = address(c).balance;

        // perform the call and catch revert
        bool reverted;
        c.sendMoney(target, value, data); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        // observe post-state
        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;
        uint balanceAfter = address(c).balance;

        // Rule: if the caller (this contract) is NOT the owner, then sendMoney must either revert
        // OR leave depositsCount and contract balance unchanged.
        assert(owner != address(this) ? (reverted || (depositsAfter == depositsBefore && balanceAfter == balanceBefore)) : true);
    }

    // receive to accept Ether forwarded by C during sendMoney
    receive() external payable {}
}

